import{_ as t,o as n,c as e,ae as s}from"./chunks/framework.DJK_dC0-.js";const g=JSON.parse('{"title":"知识库 Agent：从 Python 到真实业务系统","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/knowledge-base-agent.md","filePath":"tutorial/knowledge-base-agent.md"}'),l={name:"tutorial/knowledge-base-agent.md"};function o(i,a,r,d,p,c){return n(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="知识库-agent-从-python-到真实业务系统" tabindex="-1">知识库 Agent：从 Python 到真实业务系统 <a class="header-anchor" href="#知识库-agent-从-python-到真实业务系统" aria-label="Permalink to &quot;知识库 Agent：从 Python 到真实业务系统&quot;">​</a></h1><p>本案例以 Python 语法、数据契约、检索、工具调用、权限、评测和恢复构成终局验收合同。当前仓库的 <a href="https://github.com/zenHeart/learn-python/tree/master/examples/knowledge_base_agent" target="_blank" rel="noreferrer">教学 fixture</a> 只实现离线词元检索、ACL、文档 ID/版本引用、拒答与评测门禁；工具循环、MCP、模型调用和恢复仍是待完成的练习，整案保持 <code>verification: not-run</code>。</p><h2 id="终局任务" tabindex="-1">终局任务 <a class="header-anchor" href="#终局任务" aria-label="Permalink to &quot;终局任务&quot;">​</a></h2><p>从空目录交付一个面向脱敏测试资料的知识库 Agent：</p><ol><li>接收问题并检索版本化知识库；</li><li>返回带文档 ID 和版本的引用；</li><li>无证据时拒答或请求人工确认；</li><li>通过只读白名单工具读取摘要；</li><li>记录 query、召回结果、工具调用、错误和耗时；</li><li>用 golden set 做 recall@k、MRR、引用覆盖率和回归门禁。</li></ol><p>教学 fixture 使用标准库即可运行。后续练习需要自行实现 embedding、LLM API、MCP Server 和数据库适配器，并保持评测与安全合同。</p><h2 id="系统边界" tabindex="-1">系统边界 <a class="header-anchor" href="#系统边界" aria-label="Permalink to &quot;系统边界&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户问题</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>请求契约与权限</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>混合检索（关键词 / 向量 / RRF）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>证据过滤与引用</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Agent Loop</span></span>
<span class="line"><span>  ├─ 只读知识库工具</span></span>
<span class="line"><span>  ├─ 评测工具</span></span>
<span class="line"><span>  └─ 人工确认工具（默认停机）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>答案、引用、trace、指标</span></span></code></pre></div><p>模型只能提出工具调用，不能直接访问文件、数据库或业务系统。工具执行层负责参数校验、权限检查、超时、幂等和审计。</p><h2 id="必须掌握的机制" tabindex="-1">必须掌握的机制 <a class="header-anchor" href="#必须掌握的机制" aria-label="Permalink to &quot;必须掌握的机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>需要能解释的边界</th><th>故障题</th></tr></thead><tbody><tr><td>数据契约</td><td>类型注解不是运行时校验；外部输入必须验证</td><td>非法 top_k、未知 doc_id、越权 role</td></tr><tr><td>Agent Loop</td><td>assistant tool call 与 tool result 必须按 ID 对齐</td><td>并发返回顺序改变后结果错配</td></tr><tr><td>检索</td><td>命中率不等于答案正确；切块、召回、重排和引用是不同层</td><td>评测集命中下降但关键词检索未变</td></tr><tr><td>权限</td><td>在检索前限定授权范围，读取文档与返回引用时复核；无权内容不得进入外部重排或模型上下文</td><td>高分文档属于另一个角色</td></tr><tr><td>重试</td><td>响应丢失时先读状态，不能盲目重复副作用</td><td>已写入但响应超时</td></tr><tr><td>评测</td><td>业务成功率、检索指标、引用覆盖率和成本延迟分别度量</td><td>只看 LLM 总分掩盖召回回归</td></tr></tbody></table><h2 id="分层练习" tabindex="-1">分层练习 <a class="header-anchor" href="#分层练习" aria-label="Permalink to &quot;分层练习&quot;">​</a></h2><ol><li><strong>最小检索</strong>：实现 tokenizer、TF-IDF 或 BM25，固定排序和 tie-break。</li><li><strong>引用回答</strong>：答案只允许使用 top-k 证据，找不到依据时返回拒答。</li><li><strong>工具调用</strong>：实现 <code>get_doc</code> 和 <code>search_docs</code>，校验参数并返回结构化错误。</li><li><strong>Agent Loop</strong>：使用离线 fake model 跑通 assistant → tool → assistant。</li><li><strong>恢复故障</strong>：注入缺少 <code>tool_call_id</code>、超时、重复调用、非法参数四类错误。</li><li><strong>评测门禁</strong>：新增一条 query 后指标下降，CI 必须失败。</li><li><strong>迁移</strong>：把测试面经语料换成银行测试规则语料，增加权限和人工确认。</li></ol><h2 id="业务迁移到银行测试" tabindex="-1">业务迁移到银行测试 <a class="header-anchor" href="#业务迁移到银行测试" aria-label="Permalink to &quot;业务迁移到银行测试&quot;">​</a></h2><p>课程可以使用以下合成场景，但不能接入生产数据：</p><ul><li>手机银行转账规则与测试数据说明；</li><li>测试环境账户查询接口约束；</li><li>UI 自动化定位策略；</li><li>回归报告异常分类；</li><li>需要人工确认的高影响动作。</li></ul><p>知识库 Agent 的成功标准是“能提供可核验依据并安全停止”，不是“总能给出答案”。</p>`,17)])])}const u=t(l,[["render",o]]);export{g as __pageData,u as default};
